import{_ as r,c as a,o as i,ag as t}from"./chunks/framework.C86mscM5.js";const u=JSON.parse('{"title":"SSR (Server Side Rendering)","description":"","frontmatter":{},"headers":[],"relativePath":"advance/rendering-mode/ssr.md","filePath":"advance/rendering-mode/ssr.md","lastUpdated":1788689791000}'),n={name:"advance/rendering-mode/ssr.md"};function l(o,e,s,d,S,c){return i(),a("div",null,e[0]||(e[0]=[t('<h1 id="ssr-server-side-rendering" tabindex="-1">SSR (Server Side Rendering) <a class="header-anchor" href="#ssr-server-side-rendering" aria-label="Permalink to &quot;SSR (Server Side Rendering)&quot;">​</a></h1><blockquote><p>SSR 是 &quot;Server-Side Rendering&quot;（服务器端渲染）的缩写。它表示由服务器生成网页的 HTML，并将其发送给客户端，而不是只发送一个空的 HTML 外壳，并依赖 JavaScript 来生成页面内容。</p><p>在传统的客户端渲染中，服务器会向客户端发送一个空的 HTML 外壳和一些 JavaScript 脚本，然后从服务器的 API 中获取数据，并用动态内容填充页面。这会导致页面的初始加载时间较慢，不利于用户体验和 SEO。</p><p>使用 SSR 后，服务器会生成已经包含动态内容的 HTML，并将其发送给客户端。这使得首屏加载速度更快，并对 SEO 更加友好，因为搜索引擎可以爬取到渲染后的页面。</p></blockquote><h2 id="ssr-加载流程" tabindex="-1">SSR 加载流程 <a class="header-anchor" href="#ssr-加载流程" aria-label="Permalink to &quot;SSR 加载流程&quot;">​</a></h2><ol><li>浏览器加载 HTML → 用户立即看到完整内容</li><li>JavaScript 加载完成 → React hydrate（水合），绑定事件交互</li><li>后续页面导航 → SPA 模式，客户端渲染</li></ol><h2 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h2><ul><li><strong>首屏渲染更快</strong>：用户无需等待 JavaScript 加载和执行，浏览器加载 HTML 后即可看到完整内容，而不是在用户访问时才进行渲染。</li><li><strong>SEO 友好</strong>：搜索引擎爬虫可以直接抓取</li></ul><h2 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h2><ul><li><strong>服务器压力大</strong>：每次请求都需要服务器生成 HTML，可能会增加服务器的负载，尤其是在高流量情况下。</li><li><strong>开发复杂度高</strong>：需要在服务器端和客户端之间共享代码和状态，可能会增加开发和维护的复杂度。</li></ul><h2 id="如何提升首屏性能" tabindex="-1">如何提升首屏性能 <a class="header-anchor" href="#如何提升首屏性能" aria-label="Permalink to &quot;如何提升首屏性能&quot;">​</a></h2><ul><li>缓存（Caching）：对静态内容和 API 响应进行缓存，减少服务器渲染的压力，提高响应速度。</li><li>流式渲染（Streaming Rendering）：服务器可以在生成 HTML 的同时，将内容分块发送给客户端，减少首屏加载时间。</li></ul>',10)]))}const g=r(n,[["render",l]]);export{u as __pageData,g as default};
